import numpy as np

class LinGreedyArm:
    def __init__(self, context_dim: int, lambda_: float = 1.0):
        self.A = lambda_ * np.eye(context_dim)  # ridge regularization
        self.b = np.zeros(context_dim)

    def predict(self, context: np.ndarray) -> float:
        theta = np.linalg.solve(self.A, self.b)
        return theta @ context

    def update(self, context: np.ndarray, reward: float):
        self.A += np.outer(context, context)
        self.b += reward * context

class LinGreedyBandit:
    def __init__(self, n_arms: int, context_dim: int, epsilon: float = 0.1):
        self.arms = [LinGreedyArm(context_dim) for _ in range(n_arms)]
        self.epsilon = epsilon

    def select_arm(self, context: np.ndarray) -> int:
        if np.random.random() < self.epsilon:
            return np.random.randint(len(self.arms))  # explore
        scores = [arm.predict(context) for arm in self.arms]
        return int(np.argmax(scores))  # exploit
